212	// Normalize a state-file stage value for comparison: the field usually holds
213	// the slug (code-generation) but a display-cased value (Code Generation) must
214	// compare equal rather than silently disable enforcement.
215	export function normalizeStageName(value: string): string {
216	  return value.trim().toLowerCase().replace(/\s+/g, "-");
