222	/**
223	 * Return the distinct, non-empty target markers in encounter order. Repeated
224	 * copies of the same marker are harmless (some harnesses carry both task and
225	 * prompt-template text); different values are ambiguous and block.
226	 */
227	export function promptUnitMarkers(text: string): string[] {
228	  const units = new Set<string>();
229	  for (const line of text.split(/\r?\n/)) {
230	    const marker = line.match(UNIT_MARKER_RE);
231	    const unit = marker?.[1].trim() ?? "";
232	    if (unit.length > 0) units.add(unit);
233	  }
234	  return Array.from(units);
235	}
236	
237	export function promptStageMarkers(text: string): string[] {
238	  const stages = new Set<string>();
239	  for (const line of text.split(/\r?\n/)) {
240	    const marker = line.match(STAGE_MARKER_RE);
241	    const stage = marker?.[1].trim() ?? "";
242	    if (stage.length > 0) stages.add(normalizeStageName(stage));
243	  }
244	  return Array.from(stages);
245	}
