247	/**
248	 * The plan-approval dispatch decision. Pure: no I/O, no environment.
249	 *
250	 * Blocks when the dispatch targets the developer agent for code-generation
251	 * unless the prompt carries exactly one target marker (`AIDLC-UNIT` or the
252	 * stage-level `AIDLC-STAGE: code-generation`), that marker identifies a known
253	 * approval target, and that target has approved plan evidence.
254	 */
255	export function evaluatePlanApprovalDispatch(
256	  toolName: string,
257	  subagentType: string,
258	  promptText: string,
259	  ctx: {
260	    currentStage: string;
261	    units: UnitEvidence[];
262	  },
263	): PlanApprovalVerdict {
264	  const allow: PlanApprovalVerdict = { block: false, mentioned: [] };
265	  if (!DISPATCH_TOOLS.has(toolName)) return allow;
266	  if (subagentType !== GUARDED_AGENT) return allow;
267	  if (normalizeStageName(ctx.currentStage) !== GUARDED_STAGE) return allow;
268	
269	  const markedUnits = promptUnitMarkers(promptText);
270	  const markedStages = promptStageMarkers(promptText);
271	  const mentioned = [
272	    ...markedUnits,
273	    ...markedStages.map((stage) => `stage:${stage}`),
274	  ];
275	  if (markedUnits.length + markedStages.length !== 1) {
276	    return { block: true, mentioned };
277	  }
278	  const target =
279	    markedUnits.length === 1
280	      ? ctx.units.find((u) => u.unit === markedUnits[0])
281	      : markedStages[0] === GUARDED_STAGE
282	        ? ctx.units.find((u) => u.unit === null)
283	        : undefined;
284	  const contractMarkers = promptTestingContractMarkers(promptText);
285	  return {
286	    block:
287	      target === undefined ||
288	      !approvalEvidenceIsCurrent(target) ||
289	      contractMarkers.length !== 1 ||
290	      contractMarkers[0] !== target.contractHash,
291	    mentioned,
292	  };
293	}
