295	// The block reason handed back to the conductor through the harness's
296	// PreToolUse error channel. Self-explaining and redirecting: it names the
297	// missing evidence and the exact stage steps that produce it, so the
298	// conductor self-corrects instead of retrying the same call.
299	export function blockReason(mentioned: string[]): string {
300	  const scope =
301	    mentioned.length === 1
302	      ? mentioned[0] === `stage:${GUARDED_STAGE}`
303	        ? "the zero-Unit stage-level implementation"
304	        : `unit ${mentioned[0]}`
305	      : mentioned.length > 1
306	        ? `one target, but the brief names several (${mentioned.join(", ")})`
307	        : "one target, but the brief does not name it";
308	  return (
309	    `Code generation cannot start for ${scope} because its plan and test instructions are ` +
310	    `not currently approved. Finish Steps 2-3 in code-generation: update ` +
311	    `code-generation-plan.md and unit-test-instructions.md, refresh the Testing Contract and ` +
312	    `approval fingerprint, present Plan Approval, end the turn, and wait for the human's ` +
313	    `"Approve Plan" answer. Then retry the developer handoff with ` +
314	    `"AIDLC-UNIT: <unit>" or "AIDLC-STAGE: code-generation", followed by ` +
315	    `"AIDLC-TESTING-CONTRACT: <contract hash>".`
316	  );
317	}
