347	// The workflow's known units: the compiled bolt DAG when one resolves, plus
348	// every existing construction/<unit>/ dir (incremental scopes skip
349	// units-generation, so a conductor-chosen unit dir is the only register
350	// there). A malformed DAG contributes nothing - the dir listing still stands.
351	export function knownUnits(projectDir: string, recordDir: string): string[] {
352	  const units = new Set<string>();
353	  try {
354	    const dag = resolveBoltDag(projectDir);
355	    if (dag.state === "ok") for (const u of dag.units) units.add(u);
356	  } catch {
357	    // DAG resolution is best-effort here.
358	  }
359	  try {
360	    const constructionDir = join(recordDir, "construction");
361	    if (existsSync(constructionDir)) {
362	      for (const entry of readdirSync(constructionDir, { withFileTypes: true })) {
363	        if (entry.isDirectory() && entry.name !== GUARDED_STAGE) units.add(entry.name);
364	      }
365	    }
366	  } catch {
367	    // Unreadable construction dir - the DAG set (possibly empty) stands.
368	  }
369	  return Array.from(units);
370	}
