410	function isTrustedRecordTarget(
411	  projectDir: string,
412	  target: string,
413	  recordDir: string,
414	): boolean {
415	  try {
416	    const projectLexical = resolve(projectDir);
417	    const projectReal = realpathSync(projectLexical);
418	    const targetAbs = resolve(target);
419	    const recordAbs = resolve(recordDir);
420	    assertNoSymlinkInChainOrThrow(
421	      projectReal,
422	      relative(projectLexical, recordAbs),
423	    );
424	    assertNoSymlinkInChainOrThrow(
425	      projectReal,
426	      relative(projectLexical, targetAbs),
427	    );
428	    return isWithinDir(targetAbs, recordAbs);
429	  } catch {
430	    return false;
431	  }
