434	interface MutationIntent {
435	  targets: string[];
436	  opaqueShell: boolean;
437	  shellCommand: string | null;
438	}
439	
440	function normalizedCommandName(name: string): string {
441	  return basename(name).toLowerCase().replace(/\.exe$/, "");
442	}
443	
444	function gitSubcommand(args: string[]): string | null {
445	  for (let i = 0; i < args.length; i++) {
446	    const arg = args[i];
447	    if (["-C", "--git-dir", "--work-tree", "--namespace"].includes(arg)) {
448	      i++;
449	      continue;
450	    }
451	    if (
452	      arg.startsWith("--git-dir=") ||
453	      arg.startsWith("--work-tree=") ||
454	      arg.startsWith("--namespace=")
455	    ) {
456	      continue;
457	    }
458	    if (arg.startsWith("-")) continue;
459	    return arg;
460	  }
461	  return null;
462	}
463	
464	function isFrameworkToolInvocation(
465	  projectDir: string,
466	  cwd: string,
467	  name: string,
468	  args: string[],
469	): boolean {
470	  if (normalizedCommandName(name) !== "bun") return false;
471	  if (
472	    args.some((arg) =>
473	      arg === "-r" ||
474	      arg === "--require" ||
475	      arg === "--preload" ||
476	      arg.startsWith("--require=") ||
477	      arg.startsWith("--preload=")
478	    )
479	  ) {
480	    return false;
481	  }
482	  let scriptIndex = 0;
483	  if (args[0] === "run") scriptIndex = 1;
484	  const script = args[scriptIndex];
485	  if (!script || script.startsWith("-")) return false;
486	  const projectLexical = resolve(projectDir);
487	  const absolute = isAbsolute(script) ? resolve(script) : resolve(cwd, script);
488	  const trustedToolsDir = resolve(projectLexical, harnessDir(), "tools");
489	  if (
490	    dirname(absolute) !== trustedToolsDir ||
491	    !/^aidlc-[A-Za-z0-9._-]+\.ts$/.test(basename(absolute))
492	  ) {
493	    return false;
494	  }
495	  try {
496	    const projectReal = realpathSync(projectLexical);
497	    assertNoSymlinkInChainOrThrow(
498	      projectReal,
499	      relative(projectLexical, absolute),
500	    );
501	    return lstatSync(absolute).isFile() && !lstatSync(absolute).isSymbolicLink();
502	  } catch {
503	    return false;
504	  }
505	}
506	
507	function shellInvocationNeedsApproval(
508	  projectDir: string,
509	  cwd: string,
510	  invocation: { name: string; args: string[] },
511	  hasConcreteTargets: boolean,
512	): boolean {
513	  const name = normalizedCommandName(invocation.name);
514	  if (name === "sort") {
515	    return invocation.args.some(
516	      (arg) => arg === "-o" || arg === "--output" || arg.startsWith("--output="),
517	    );
518	  }
519	  if (name === "uniq") {
520	    const operands = invocation.args.filter((arg) => !arg.startsWith("-"));
521	    return operands.length >= 2;
522	  }
523	  if (READ_ONLY_SHELL_COMMANDS.has(name)) return false;
524	  if (name === "git") {
525	    if (
526	      invocation.args.some(
527	        (arg) => arg === "--output" || arg.startsWith("--output="),
528	      )
529	    ) {
530	      return true;
531	    }
532	    const subcommand = gitSubcommand(invocation.args);
533	    if (subcommand === "branch") {
534	      return !invocation.args.includes("--show-current");
535	    }
536	    return subcommand === null || !READ_ONLY_GIT_SUBCOMMANDS.has(subcommand);
537	  }
538	  if (isFrameworkToolInvocation(projectDir, cwd, name, invocation.args)) return false;
539	  if (
540	    TRACKED_SHELL_MUTATORS.has(name) &&
541	    hasConcreteTargets &&
542	    !invocation.args.some((arg) => /[$`*?]/.test(arg))
543	  ) {
544	    return false;
545	  }
546	  return true;
547	}
548	
549	function shellUsesDynamicEvaluation(command: string): boolean {
550	  let quote: "'" | '"' | null = null;
551	  let escaped = false;
552	  for (let i = 0; i < command.length; i++) {
553	    const ch = command[i];
554	    if (escaped) {
555	      escaped = false;
556	      continue;
557	    }
558	    if (ch === "\\" && quote !== "'") {
559	      escaped = true;
560	      continue;
561	    }
562	    if (quote === "'") {
563	      if (ch === "'") quote = null;
564	      continue;
565	    }
566	    if (ch === '"') {
567	      quote = quote === '"' ? null : '"';
568	      continue;
569	    }
570	    if (ch === "'" && quote === null) {
571	      quote = "'";
572	      continue;
573	    }
574	    if (ch === "`" || ch === "$") return true;
575	    if ((ch === "$" || ch === "<" || ch === ">") && command[i + 1] === "(") {
576	      return true;
577	    }
578	  }
579	  return false;
580	}
581	
582	async function mutationIntent(
583	  projectDir: string,
584	  toolName: string,
585	  toolInput: Record<string, unknown> | undefined,
586	  cwd: string,
587	): Promise<MutationIntent> {
588	  let targets: string[] = [];
589	  let opaqueShell = false;
590	  let shellCommand: string | null = null;
591	  if (toolName === "Bash") {
592	    const command = toolInput?.command;
593	    if (typeof command !== "string") {
594	      return { targets: [], opaqueShell: false, shellCommand: null };
595	    }
596	    shellCommand = command;
597	    const { shellCommandInvocations, shellWriteTargets } = await import(
598	      "./aidlc-review-freeze.ts"
599	    );
600	    targets = shellWriteTargets(command, cwd);
601	    opaqueShell =
602	      shellUsesDynamicEvaluation(command) ||
603	      shellCommandInvocations(command).some((invocation) =>
604	        shellInvocationNeedsApproval(projectDir, cwd, invocation, targets.length > 0)
605	      );
606	  } else if (WRITE_TOOLS.has(toolName)) {
607	    const input = toolInput ?? {};
608	    const add = (value: unknown) => {
609	      if (typeof value === "string" && value.length > 0) targets.push(value);
610	    };
611	    add(input.file_path);
612	    add(input.notebook_path);
613	    add(input.path);
614	    if (Array.isArray(input.paths)) for (const path of input.paths) add(path);
615	  }
616	  return {
617	    targets: targets.map((target) =>
618	      isAbsolute(target) ? resolve(target) : resolve(cwd, target)
619	    ),
620	    opaqueShell,
621	    shellCommand,
622	  };
623	}
