625	// --- Main ---------------------------------------------------------------------
626	
627	export async function run(input: string): Promise<number> {
628	  // Deterministic off-switch: enforcement disabled entirely.
629	  if (process.env.AIDLC_DISABLE_PLAN_APPROVAL_GUARD === "1") return 0;
630	
631	  const projectDir = resolveProjectDirFromHook(import.meta.url);
632	
633	  try {
634	    const healthDir = hooksHealthDir(projectDir);
635	    mkdirSync(healthDir, { recursive: true });
636	    writeFileSync(join(healthDir, `${HOOK_NAME}.last`), isoTimestamp(), "utf-8");
637	  } catch {
638	    // Heartbeat failure is non-fatal - never let it affect the decision.
639	  }
640	
641	  // A TTY means no harness JSON is coming (test / debug contexts) - allow.
642	  if (process.stdin.isTTY) return 0;
643	
644	  let parsed: ClaudeCodeHookInput;
645	  try {
646	    const raw: unknown = JSON.parse(input);
647	    if (!isClaudeCodeHookInput(raw)) return 0;
648	    parsed = raw;
649	  } catch {
650	    return 0; // malformed stdin - fail open
651	  }
652	
653	  const toolName = parsed.tool_name ?? "";
654	  const toolInput = parsed.tool_input ?? {};
655	  const subagentType =
656	    typeof toolInput.subagent_type === "string" ? toolInput.subagent_type : "";
657	  const guardedDispatch =
658	    DISPATCH_TOOLS.has(toolName) && subagentType === GUARDED_AGENT;
659	  if (SAFE_READ_TOOLS.has(toolName)) return 0;
660	  const mutationCapable =
661	    toolName === "Bash" ||
662	    WRITE_TOOLS.has(toolName) ||
663	    (!DISPATCH_TOOLS.has(toolName) && toolName.length > 0);
664	  if (!guardedDispatch && !mutationCapable) return 0;
665	  const cwd = typeof parsed.cwd === "string" ? parsed.cwd : projectDir;
666	
667	  let verdict: PlanApprovalVerdict;
668	  let units: UnitEvidence[] = [];
669	  let authorityFailure: string | null = null;
670	  let blockedMutation: {
671	    target: string;
672	    unit: string | null;
673	    opaqueShell: boolean;
674	  } | null = null;
675	  try {
676	    const statePath = stateFilePath(projectDir);
677	    if (!existsSync(statePath)) return 0; // no workflow - fail open
678	    const state = readFileSync(statePath, "utf-8");
679	    const currentStage = getField(state, "Current Stage") ?? "";
680	    const activeDirective = readActiveDirectiveMarker(projectDir, state);
681	    const durableStage = normalizeStageName(currentStage);
682	    const directiveStage = normalizeStageName(activeDirective?.stage ?? "");
683	    const dispatchPrompt = [toolInput.prompt, toolInput.description]
684	      .filter((value): value is string => typeof value === "string")
685	      .join("\n");
686	    const explicitPlanDispatch =
687	      promptUnitMarkers(dispatchPrompt).length > 0 ||
688	      promptStageMarkers(dispatchPrompt).length > 0 ||
689	      promptTestingContractMarkers(dispatchPrompt).length > 0;
690	    const codeGenerationRelevant =
691	      directiveStage === GUARDED_STAGE ||
692	      durableStage === GUARDED_STAGE ||
693	      (guardedDispatch && explicitPlanDispatch);
694	    if (!codeGenerationRelevant) return 0;
695	    const knownMutationTool =
696	      toolName === "Bash" || WRITE_TOOLS.has(toolName);
697	    const mutation = guardedDispatch
698	      ? { targets: [], opaqueShell: false, shellCommand: null }
699	      : knownMutationTool
700	        ? await mutationIntent(projectDir, toolName, toolInput, cwd)
701	        : {
702	            targets: [],
703	            opaqueShell: true,
704	            shellCommand: `unknown mutation-capable tool: ${toolName}`,
705	          };
706	    if (!guardedDispatch && mutation.targets.length === 0 && !mutation.opaqueShell) {
707	      return 0;
708	    }
709	
710	    if (
711	      activeDirective?.version !== 2 ||
712	      directiveStage !== GUARDED_STAGE
713	    ) {
714	      authorityFailure =
715	        "the current state has no matching v2 code-generation active directive";
716	      verdict = { block: true, mentioned: [] };
717	    } else {
718	      const recordDir = docsRoot(projectDir);
719	      units = gatherApprovalEvidence(projectDir, knownUnits(projectDir, recordDir));
720	      if (guardedDispatch) {
721	        verdict = evaluatePlanApprovalDispatch(toolName, subagentType, dispatchPrompt, {
722	          currentStage: activeDirective.stage,
723	          units,
724	        });
725	      } else if (activeDirective.kind !== "run-stage") {
726	        authorityFailure =
727	          `workspace mutation cannot select one approval target from directive kind "${activeDirective.kind}"`;
728	        verdict = { block: true, mentioned: [] };
729	      } else {
730	        const unit = activeDirective.unit?.trim() || null;
731	        const target: CodeGenerationTarget = { unit };
732	        const approvalDir = resolve(codeGenerationRecordDir(projectDir, unit));
733	        const outsideRecord = mutation.targets.find(
734	          (candidate) =>
735	            !isTrustedRecordTarget(projectDir, candidate, approvalDir),
736	        );
737	        if (!outsideRecord && !mutation.opaqueShell) return 0;
738	        const approval = evaluateCodeGenerationApproval(projectDir, target);
739	        const evidence: UnitEvidence = {
740	          unit,
741	          planExists: approval.planExists,
742	          instructionsExist: approval.instructionsExist,
743	          approved: approval.approved,
744	          contractValid: approval.contractValid,
745	          fingerprintValid: approval.fingerprintValid,
746	          receiptValid: approval.receiptValid,
747	          contractHash: approval.contractHash,
748	        };
749	        verdict = {
750	          block: !approvalEvidenceIsCurrent(evidence),
751	          mentioned: [unit ?? `stage:${GUARDED_STAGE}`],
752	        };
753	        if (verdict.block) {
754	          blockedMutation = {
755	            target:
756	              outsideRecord ??
757	              `shell command: ${(mutation.shellCommand ?? "").trim().slice(0, 160)}`,
758	            unit,
759	            opaqueShell: outsideRecord === undefined,
760	          };
761	        }
762	      }
763	    }
764	  } catch (e) {
765	    recordHookDrop(projectDir, HOOK_NAME, errorMessage(e));
766	    authorityFailure =
767	      `Plan Approval authority evaluation failed closed: ${errorMessage(e)}`;
768	    verdict = { block: true, mentioned: [] };
769	  }
770	  if (!verdict.block) {
771	    try {
772	      if (guardedDispatch) {
773	        for (const mentioned of verdict.mentioned) {
774	          beginCodeGeneration(projectDir, {
775	            unit:
776	              mentioned === `stage:${GUARDED_STAGE}` ? null : mentioned,
777	          });
778	        }
779	      } else if (blockedMutation === null) {
780	        const state = readFileSync(stateFilePath(projectDir), "utf-8");
781	        const marker = readActiveDirectiveMarker(projectDir, state);
782	        if (marker?.version === 2 && marker.kind === "run-stage") {
783	          beginCodeGeneration(projectDir, {
784	            unit: marker.unit?.trim() || null,
785	          });
786	        }
787	      }
788	    } catch (e) {
789	      authorityFailure =
790	        `Code Generation could not start from its protected approval receipt: ${errorMessage(e)}`;
791	      verdict = { block: true, mentioned: verdict.mentioned };
792	    }
793	  }
794	  if (!verdict.block) return 0;
795	
796	  // Audit the refusal so the run's record shows when the ordering bit.
797	  // Best-effort: an audit failure never changes the block decision. The lock
798	  // acquisition is TIME-BOUNDED well below the standard 5s budget (5 x 50ms):
799	  // the block decision is already made, and a dropped advisory row is
800	  // preferable to a slow block.
801	  try {
802	    if (existsSync(auditFilePath(projectDir))) {
803	      if (acquireAuditLock(projectDir, 5, 50)) {
804	        try {
805	          appendAuditEntryUnlocked(
806	            "PLAN_APPROVAL_BLOCKED",
807	            {
808	              Tool: toolName,
809	              Target: guardedDispatch ? subagentType : blockedMutation?.target ?? "",
810	              Stage: GUARDED_STAGE,
811	              Unit:
812	                blockedMutation?.unit ??
813	                (verdict.mentioned[0] === `stage:${GUARDED_STAGE}`
814	                  ? STAGE_TARGET
815	                  : verdict.mentioned.join(", ") || "(missing marker)"),
816	            },
817	            projectDir,
818	          );
819	        } finally {
820	          releaseAuditLock(projectDir);
821	        }
822	      } else {
823	        recordHookDrop(
824	          projectDir,
825	          HOOK_NAME,
826	          "audit lock contended; PLAN_APPROVAL_BLOCKED row dropped (block still enforced)",
827	        );
828	      }
829	    }
830	  } catch {
831	    // Advisory emission only.
832	  }
833	
834	  process.stderr.write(
835	    `${authorityFailure
836	      ? authorityBlockReason(authorityFailure)
837	      : blockedMutation
838	      ? mutationBlockReason(
839	          blockedMutation.target,
840	          blockedMutation.unit,
841	          blockedMutation.opaqueShell,
842	        )
843	      : blockReason(verdict.mentioned)}\n`,
844	  );
845	  return 2; // harness PreToolUse reject contract: exit 2 + stderr blocks
846	}
847	
848	if (import.meta.main) {
849	  const input = process.stdin.isTTY ? "" : await Bun.stdin.text();
850	  process.exit(await run(input));
851	}
