   if($ok -lt $o.Count -and $o[$ok] -ne $n[$k]){ "  DIFF line$($k+1): OLD[$($o[$ok])] NEW[$($n[$k])]" }
 }
 # pipe audit
 $hdr=($n | Where-Object { $_ -match '^\| ID \| Severity' })
 foreach($l in $n){
   if($l.StartsWith('|')){
     $c=([regex]::Matches($l,'(?<!\\)\|')).Count
     if(-not $script:pc){ }
     "  PIPE $c :: $($l.Substring(0,[Math]::Min(45,$l.Length)))"
   }
 }
}

