arguments.content:
# -*- coding: utf-8 -*-
"""Step 10 of Build and Test: the cross-unit final coverage gate.

Enumerates every leaf FR, every NFR and every three-segment AC, then checks each
against the five per-unit code-generation traceability files. FR coverage is
transitive through the stories that declare it, because the per-unit files track
acceptance criteria and business rules, never requirement ids.
"""
import io
import json
import os
import re
import sys
from collections import OrderedDict

sys.stdout.reconfigure(encoding="utf-8")

ROOT = r"C:\projetos-pessoais\academic-support-ticket"
REC = os.path.join(ROOT, r"aidlc\spaces\default\intents\260907-chamados-academicos")
UNITS = ["u1-foundation", "u2-tickets", "u3-conversation", "u4-reporting", "u5-rating"]
OUT = os.path.join(REC, r"construction\build-and-test\cross-unit-traceability.md")

req_text = io.open(os.path.join(REC, r"inception\requirements-analysis\requirements.md"), encoding="utf-8").read()
stories_text = io.open(os.path.join(REC, r"inception\user-stories\stories.md"), encoding="utf-8").read()

# --- enumerate ---------------------------------------------------------------
leaf_fr = sorted(
    {m.group(0) for m in re.finditer(r"(?m)^\| (FR\d+\.\d+) \|", req_text.replace("| FR", "| FR"))}
    | {m.group(1) for m in re.finditer(r"(?m)^\|\s*(FR\d+\.\d+)\s*\|", req_text)},
    key=lambda s: [int(x) for x in re.findall(r"\d+", s)],
)
nfr = sorted(
    {m.group(1) for m in re.finditer(r"(?m)^\|\s*(NFR\d+)\s*\|", req_text)},
    key=lambda s: int(re.findall(r"\d+", s)[0]),
)
acs = sorted(
    {m.group(0) for m in re.finditer(r"\bAC\d+\.\d+\.\d+\b", stories_text)},
    key=lambda s: [int(x) for x in re.findall(r"\d+", s)],
)

# --- story -> FR map ---------------------------------------------------------
story_fr = OrderedDict()
blocks = re.split(r"(?m)^### (US\d+\.\d+)[^\n]*$", stories_text)
for i in range(1, len(blocks), 2):
    story, body = blocks[i], blocks[i + 1]
    covers = re.search(r"(?m)^\s*(?:\*\*)?Cobre(?:\*\*)?:\s*(.+)$", body)
    frs = sorted({m.group(0) for m in re.finditer(r"\bFR\d+\.\d+\b", covers.group(1))}) if covers else []
    story_fr[story] = frs

# --- traceability entries ----------------------------------------------------
entries = {}
for unit in UNITS:
    path = os.path.join(REC, "construction", unit, "code-generation", "traceability.json")
    data = json.load(io.open(path, encoding="utf-8"))
    for e in data.get("coverage", []):
        entries.setdefault(e["id"], []).append((unit, e.get("status"), e.get("target", "")))


def target_exists(target):
    """A target is a repository path; rule ids and prose are not checkable paths."""
    if not target or not re.match(r"^(apps|docs|scripts)[/\\]", target):
        return None
    return os.path.exists(os.path.join(ROOT, target.replace("/", os.sep)))


def ac_verdict(ac):
    rows = entries.get(ac, [])
    for unit, status, target in rows:
        if status == "OK":
            ex = target_exists(target)
            if ex is False:
                return ("FAIL", unit, target, "alvo citado nao existe em disco")
            return ("OK", unit, target, "")
    if not rows:
        return ("FAIL", "", "", "nenhuma unidade registra este critério")
    unit, status, target = rows[0]
    return ("FAIL", unit, target, "registrado apenas como %s" % status)


ac_results = OrderedDict((ac, ac_verdict(ac)) for ac in acs)

# --- FR coverage, transitive through the stories -----------------------------
fr_results = OrderedDict()
for fr in leaf_fr:
    stories = [s for s, frs in story_fr.items() if fr in frs]
    covering = []
    for s in stories:
        n, m = re.findall(r"\d+", s)
        for ac in acs:
            if ac.startswith("AC%s.%s." % (n, m)) and ac_results[ac][0] == "OK":
                covering.append((s, ac))
    if covering:
        fr_results[fr] = ("OK", ", ".join(s for s, _ in dict.fromkeys(s for s, _ in covering)), covering[0][1], "")
    elif stories:
        fr_results[fr] = ("FAIL", ", ".join(stories), "", "as historias que o declaram nao tem critério coberto")
    else:
        fr_results[fr] = ("FAIL", "", "", "nenhuma historia declara cobrir este requisito")

ac_fail = [a for a, r in ac_results.items() if r[0] != "OK"]
fr_fail = [f for f, r in fr_results.items() if r[0] != "OK"]

print("FR folha: %d (falhas %d)" % (len(leaf_fr), len(fr_fail)))
print("NFR: %d (verificados fora da rastreabilidade por critério próprio)" % len(nfr))
print("AC de tres segmentos: %d (falhas %d)" % (len(acs), len(ac_fail)))
if ac_fail:
    print("AC sem cobertura:", ", ".join(ac_fail))
if fr_fail:
    print("FR sem cobertura:", ", ".join(fr_fail))

io.open(os.path.join(r"C:\Users\Administrador\AppData\Local\Temp\aidlc-bt", "crossunit.json"), "w", encoding="utf-8").write(
    json.dumps(
        {
            "leaf_fr": leaf_fr,
            "nfr": nfr,
            "acs": acs,
            "ac_results": {k: list(v) for k, v in ac_results.items()},
            "fr_results": {k: list(v) for k, v in fr_results.items()},
            "story_fr": story_fr,
        },
        ensure_ascii=False,
        indent=1,
    )
)
print("dados salvos em crossunit.json")

